patch:
diff --git a/repro/no-lonely-if-19033.js b/repro/no-lonely-if-19033.js
new file mode 100644
index 0000000..6b851e7
--- /dev/null
+++ b/repro/no-lonely-if-19033.js
@@ -0,0 +1,54 @@
+"use strict";
+
+// Reproduction for no-lonely-if autofix changing `else` binding (reported against 9.12.0).
+const assert = require("node:assert");
+const { Linter } = require(process.env.ESLINT_PATH || "../lib/api");
+
+const linter = new Linter();
+const config = { rules: { "no-lonely-if": "error" } };
+
+const reportCode = [
+    "if (true)",
+    "\tif (false) {}",
+    "\telse { if (false) {} }",
+    "else throw Error('This `else` should have been unreachable!');"
+].join("\n");
+
+// Existing valid test case in tests/lib/rules/no-lonely-if.js: same shape, outer `else` is a block.
+const validTestCode = "if (a) if (a) {} else { if (b) {} } else {}";
+
+
+function run(code) {
+    const messages = linter.verify(code, config);
+    const { output, fixed } = linter.verifyAndFix(code, config);
+    return { messages, output, fixed };
+}
+
+function behaviour(code) {
+    try {
+        new Function(code)();
+        return "no throw";
+    } catch (e) {
+        return `throws: ${e.message}`;
+    }
+}
+
+for (const [label, code] of [["report input", reportCode], ["existing valid test", validTestCode]]) {
+    const { messages, output, fixed } = run(code);
+    console.log(`=== ${label} ===`);
+    console.log(code);
+    console.log("--- messages:", messages.map(m => `${m.line}:${m.column} ${m.ruleId} ${m.message}`));
+    console.log("--- fixed:", fixed);
+    if (fixed) console.log(output);
+    console.log();
+}
+
+const { output } = run(reportCode);
+console.log("runtime before fix:", behaviour(reportCode));
+console.log("runtime after fix: ", behaviour(output));
+
+assert.strictEqual(
+    behaviour(output),
+    behaviour(reportCode),
+    "no-lonely-if autofix changed program behaviour: the outer `else` now binds to the inner `if`"
+);
